<?php
namespace ProjectPress\Includes\Project\Core;
use ProjectPress\Includes\Core\WP\Database;
use ProjectPress\Includes\Pages\Taxonomies;
use Throwable;
if(!defined('ABSPATH')){exit;}
final class ProjectRepository{
 private ProjectHydrator $hydrator;
 public function __construct(?ProjectHydrator $hydrator=null){$this->hydrator=$hydrator??new ProjectHydrator();}
 public function find(int $id):?Project{return $this->find_by('id',$id);}public function find_by_key(string $key):?Project{return $this->find_by('project_key',$key);}public function find_by_slug(string $slug):?Project{return $this->find_by('project_slug',$slug);}
 private function find_by(string $column,$value):?Project{global $wpdb;$table=Database::table_name('projects');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE {$column} = %s LIMIT 1",$value),ARRAY_A);return is_array($row)?$this->hydrator->hydrate($row):null;}
 public function query(ProjectQuery $query):array{global $wpdb;$parts=$this->query_parts($query);$args=$query->to_array();$table=Database::table_name('projects');$allowed=array('id','project_name','status','priority','start_date','target_end_date','created_at','updated_at');$order_by=in_array($args['order_by'],$allowed,true)?$args['order_by']:'updated_at';$offset=($args['page']-1)*$args['per_page'];$sql="SELECT DISTINCT p.* FROM {$table} p {$parts['joins']} WHERE ".implode(' AND ',$parts['where'])." ORDER BY p.{$order_by} {$args['order']} LIMIT %d OFFSET %d";$values=array_merge($parts['values'],array($args['per_page'],$offset));$rows=$wpdb->get_results($wpdb->prepare($sql,$values),ARRAY_A);return array_map(array($this->hydrator,'hydrate'),is_array($rows)?$rows:array());}
 public function count(ProjectQuery $query):int{global $wpdb;$parts=$this->query_parts($query);$table=Database::table_name('projects');$sql="SELECT COUNT(DISTINCT p.id) FROM {$table} p {$parts['joins']} WHERE ".implode(' AND ',$parts['where']);return(int)($parts['values']?$wpdb->get_var($wpdb->prepare($sql,$parts['values'])):$wpdb->get_var($sql));}
 private function query_parts(ProjectQuery $query):array{global $wpdb;$args=$query->to_array();$where=array('1=1');$where_values=array();$join_values=array();$joins='';foreach(array('status','priority','visibility')as$field){if(''!==$args[$field]){$where[]="p.{$field} = %s";$where_values[]=$args[$field];}}foreach(array('owner_id','parent_id')as$field){if($args[$field]>0){$where[]="p.{$field} = %d";$where_values[]=$args[$field];}}if(''!==$args['search']){$like='%'.$wpdb->esc_like($args['search']).'%';$where[]='(p.project_name LIKE %s OR p.project_description LIKE %s OR p.project_key LIKE %s)';array_push($where_values,$like,$like,$like);}$filters=array('project_type'=>Taxonomies::PROJECT_TYPE,'project_category'=>Taxonomies::PROJECT_CATEGORY,'project_tag'=>Taxonomies::PROJECT_TAG,'project_label'=>Taxonomies::PROJECT_LABEL);$i=0;foreach($filters as$key=>$taxonomy){if($args[$key]>0){$alias='ptr'.++$i;$joins.=' INNER JOIN '.Database::table_name('project_term_relationships')." {$alias} ON {$alias}.project_id = p.id AND {$alias}.taxonomy = %s AND {$alias}.term_id = %d";$join_values[]=$taxonomy;$join_values[]=$args[$key];}}return array('joins'=>$joins,'where'=>$where,'values'=>array_merge($join_values,$where_values));}
 public function insert(Project $project){global $wpdb;$data=array_filter($this->hydrator->extract($project),static fn($value)=>null!==$value);$data['created_at']=current_time('mysql',true);$data['updated_at']=$data['created_at'];$result=$wpdb->insert(Database::table_name('projects'),$data);return false===$result?false:(int)$wpdb->insert_id;}
 public function update(Project $project):bool{if($project->get_id()<1)return false;global $wpdb;$data=$this->hydrator->extract($project);unset($data['created_by']);$data['updated_at']=current_time('mysql',true);return false!==$wpdb->update(Database::table_name('projects'),$data,array('id'=>$project->get_id()));}
 public function delete(int $id):bool{global $wpdb;$id=absint($id);if($id<1)return false;$wpdb->query('START TRANSACTION');try{$children_updated=$wpdb->update(Database::table_name('projects'),array('parent_id'=>null),array('parent_id'=>$id),array('%d'),array('%d'));if(false===$children_updated)throw new \RuntimeException('Could not detach child projects.');$tables=array('project_term_relationships','project_teams','project_field_values','activity','tasks','milestones','requirements','features','user_stories','risks','issues','dependencies','decisions','discussions','notes','files','project_settings');foreach($tables as$table){if(false===$wpdb->delete(Database::table_name($table),array('project_id'=>$id),array('%d')))throw new \RuntimeException('Could not remove project-owned records.');}$relationships=Database::table_name('project_relationships');$relationship_result=$wpdb->query($wpdb->prepare("DELETE FROM {$relationships} WHERE source_project_id = %d OR target_project_id = %d",$id,$id));if(false===$relationship_result)throw new \RuntimeException('Could not remove project relationships.');$deleted=$wpdb->delete(Database::table_name('projects'),array('id'=>$id),array('%d'));if(1!==$deleted)throw new \RuntimeException('Could not remove project.');$wpdb->query('COMMIT');return true;}catch(Throwable $error){$wpdb->query('ROLLBACK');return false;}}
}
